import SwiftUI
import UniformTypeIdentifiers
import LearningSprintCore

struct HistoryView: View {
    @EnvironmentObject private var store: KanriLearningStore
    private var mastery: Double { Double(store.uniqueAnsweredCount) / 600.0 }
    var body: some View {
        ZStack { LearningSprintPaperBackground(); ScrollView { VStack(alignment:.leading,spacing:18) {
            Text("学習記録").font(LearningSprintTheme.serif(36,weight:.bold)); Text("積み上げを、見える形に。").foregroundStyle(LearningSprintTheme.ink2)
            HStack(spacing:22){ZStack{Circle().stroke(LearningSprintTheme.line,lineWidth:12);Circle().trim(from:0,to:min(1,mastery)).stroke(LearningSprintTheme.vermilion,style:StrokeStyle(lineWidth:12,lineCap:.butt)).rotationEffect(.degrees(-90));VStack(spacing:3){Text("\(Int((mastery*100).rounded()))%").font(LearningSprintTheme.serif(30,weight:.bold));Text("達成度").font(.caption.bold()).foregroundStyle(LearningSprintTheme.ink3)}.frame(maxWidth:.infinity,maxHeight:.infinity,alignment:.center)}.frame(width:118,height:118).accessibilityElement(children:.combine).accessibilityLabel("総合達成度").accessibilityValue("\(Int((mastery*100).rounded()))パーセント");HStack{metric("解答","\(store.state.attempts.count)");metric("正答率",store.state.attempts.isEmpty ? "—":"\(store.accuracy)%");metric("苦手","\(store.weakCount)")}}.padding(18).background(LearningSprintTheme.card).clipShape(RoundedRectangle(cornerRadius:20))
            sectionTitle("試験回別");ForEach(1...3,id:\.self){r in VStack(alignment:.leading,spacing:8){HStack{Text("第\(r)回").font(.headline);Spacer();Text("\(store.answeredCount(round:r)) / 200問").foregroundStyle(LearningSprintTheme.ink3)};ProgressView(value:Double(store.answeredCount(round:r)),total:200).tint(LearningSprintTheme.indigo);Text("模試完答 \(store.mockCompletionCount(round:r))回").font(.caption).foregroundStyle(LearningSprintTheme.ink2)}.padding(16).background(LearningSprintTheme.card).clipShape(RoundedRectangle(cornerRadius:16))}
            sectionTitle("分野別");VStack(spacing:12){ForEach(KanriAppConfig.subjects,id:\.self){s in let a=store.subjectAccuracy(s);VStack(alignment:.leading,spacing:5){HStack{Text(s);Spacer();Text(a.map{"\($0)%"} ?? "—").foregroundStyle(LearningSprintTheme.ink3)};ProgressView(value:Double(a ?? 0),total:100).tint(a==nil ? LearningSprintTheme.line:LearningSprintTheme.indigo)}}}.padding(16).background(LearningSprintTheme.card).clipShape(RoundedRectangle(cornerRadius:16))
            sectionTitle("5週間の学習");LearningSprintHeatmap(values:store.heatmap).padding(16).frame(maxWidth:.infinity,alignment:.leading).background(LearningSprintTheme.card).clipShape(RoundedRectangle(cornerRadius:16))
            sectionTitle("苦手一覧");let ids=Set(store.state.weakQuestions.keys);let weak=store.questions.filter{ids.contains($0.id)};if weak.isEmpty{Text("現在の苦手問題はありません。").foregroundStyle(LearningSprintTheme.ink2).padding(16).frame(maxWidth:.infinity,alignment:.leading).background(LearningSprintTheme.card).clipShape(RoundedRectangle(cornerRadius:16))}else{VStack(spacing:0){ForEach(weak.prefix(30)){q in HStack{VStack(alignment:.leading){Text(q.subject).font(.caption).foregroundStyle(LearningSprintTheme.indigo);Text(q.topic).font(.subheadline.bold())};Spacer();Text("\(store.state.weakQuestions[q.id]?.consecutiveCorrect ?? 0)/3").font(.caption.bold())}.padding(.vertical,10);Divider()}}.padding(.horizontal,16).background(LearningSprintTheme.card).clipShape(RoundedRectangle(cornerRadius:16))}
        }.padding(20).padding(.bottom,28)}}.accessibilityIdentifier("historyView")
    }
    private func sectionTitle(_ t:String)->some View{Text(t).font(LearningSprintTheme.serif(22,weight:.bold))}
    private func metric(_ t:String,_ v:String)->some View{VStack(spacing:4){Text(t).font(.caption).foregroundStyle(LearningSprintTheme.ink3);Text(v).font(.headline).foregroundStyle(LearningSprintTheme.indigo)}.frame(maxWidth:.infinity)}
}

struct BackupDocument: FileDocument {
    static var readableContentTypes:[UTType]{[.json]};var data=Data();init(data:Data=Data()){self.data=data};init(configuration:ReadConfiguration)throws{data=configuration.file.regularFileContents ?? Data()};func fileWrapper(configuration:WriteConfiguration)throws->FileWrapper{FileWrapper(regularFileWithContents:data)}
}

struct SettingsView: View {
    @EnvironmentObject private var store:KanriLearningStore
    @EnvironmentObject private var purchase:PurchaseController
    @State private var exporting=false;@State private var importing=false;@State private var exportDocument=BackupDocument();@State private var resetConfirm=false;@State private var examEnabled=false;@State private var examDate=Date()
    var body:some View{ZStack{LearningSprintPaperBackground();ScrollView{VStack(alignment:.leading,spacing:18){Text("設定").font(LearningSprintTheme.serif(36,weight:.bold));settingsCard("1日の目標"){HStack(spacing:8){ForEach([4,8,16],id:\.self){n in Button("\(n)問"){store.setDailyTarget(n)}.frame(maxWidth:.infinity,minHeight:44).background(store.state.dailyTarget==n ? LearningSprintTheme.indigoSoft:LearningSprintTheme.paper).foregroundStyle(store.state.dailyTarget==n ? LearningSprintTheme.indigo:LearningSprintTheme.ink2).clipShape(RoundedRectangle(cornerRadius:10)).accessibilityIdentifier("goal\(n)Button")}}};settingsCard("出題"){Toggle("出題順をシャッフル",isOn:Binding(get:{store.shuffleQuestions},set:{store.setShuffleQuestions($0)})).accessibilityIdentifier("shuffleQuestionsToggle");Toggle("選択肢もシャッフル",isOn:Binding(get:{store.shuffleChoices},set:{store.setShuffleChoices($0)})).accessibilityIdentifier("shuffleChoicesToggle")};settingsCard("試験日"){Toggle("試験日を登録",isOn:$examEnabled).onChange(of:examEnabled){e in store.setExamDate(e ? examDate:nil)};if examEnabled{DatePicker("試験日",selection:$examDate,displayedComponents:.date).onChange(of:examDate){store.setExamDate($0)}}};settingsCard("文字サイズ"){HStack(spacing:8){ForEach(FontChoice.allCases){c in Button(c.title){store.setTextSizeStep(c.rawValue)}.frame(maxWidth:.infinity,minHeight:44).background(store.state.textSizeStep==c.rawValue ? LearningSprintTheme.indigoSoft:LearningSprintTheme.paper).clipShape(RoundedRectangle(cornerRadius:10)).accessibilityIdentifier("font\(c.rawValue)Button")}}};settingsCard("プレミアム"){HStack{VStack(alignment:.leading){Text(store.isPremium ? "全600問 解放済み":"無料60問").font(.headline);Text(store.isPremium ? "第1〜第3回と模試を利用できます":"購入すると全600問・模試3回を解放").font(.caption).foregroundStyle(LearningSprintTheme.ink2)};Spacer()};if !store.isPremium{Button(purchase.displayPrice.map{"プレミアムを購入（\($0)）"} ?? "価格を取得中"){Task{await purchase.purchase()}}.buttonStyle(.borderedProminent).tint(LearningSprintTheme.indigo).disabled(purchase.product==nil).frame(minHeight:44).accessibilityIdentifier("purchaseButton")};Button("購入を復元"){Task{await purchase.restore()}}.buttonStyle(.bordered).tint(LearningSprintTheme.indigo).frame(minHeight:44).accessibilityIdentifier("restoreButton")};settingsCard("学習データ"){Button("JSONバックアップを書き出す"){do{exportDocument=BackupDocument(data:try store.exportBackup());exporting=true}catch{store.importMessage=error.localizedDescription}}.buttonStyle(.bordered).tint(LearningSprintTheme.indigo).frame(minHeight:44).accessibilityIdentifier("jsonExportButton");Button("JSONバックアップを読み込む"){importing=true}.buttonStyle(.bordered).tint(LearningSprintTheme.indigo).frame(minHeight:44).accessibilityIdentifier("jsonImportButton");Button("学習データをリセット",role:.destructive){resetConfirm=true}.frame(minHeight:44)};Text("UI Master v2.1準拠・純SwiftUI Native・600問オフライン同梱").font(.footnote).foregroundStyle(LearningSprintTheme.ink3)}.padding(20).padding(.bottom,28)}}.accessibilityIdentifier("settingsView").onAppear{if let d=store.state.examDate{examDate=d;examEnabled=true}}.fileExporter(isPresented:$exporting,document:exportDocument,contentType:.json,defaultFilename:"kanrieiyoushi-learning-backup"){_ in}.fileImporter(isPresented:$importing,allowedContentTypes:[.json]){result in switch result{case .success(let url):let granted=url.startAccessingSecurityScopedResource();defer{if granted{url.stopAccessingSecurityScopedResource()}};do{store.importBackup(try Data(contentsOf:url))}catch{store.importMessage=error.localizedDescription};case .failure(let e):store.importMessage=e.localizedDescription}}.alert("学習データ",isPresented:Binding(get:{store.importMessage != nil},set:{if !$0{store.importMessage=nil}})){Button("OK",role:.cancel){store.importMessage=nil}}message:{Text(store.importMessage ?? "")}.confirmationDialog("学習データをすべて削除しますか？",isPresented:$resetConfirm,titleVisibility:.visible){Button("削除",role:.destructive){store.resetLearningData()};Button("キャンセル",role:.cancel){}}
    }
    private func settingsCard<Content:View>(_ title:String,@ViewBuilder content:()->Content)->some View{VStack(alignment:.leading,spacing:12){Text(title).font(.headline);content()}.padding(16).frame(maxWidth:.infinity,alignment:.leading).background(LearningSprintTheme.card).clipShape(RoundedRectangle(cornerRadius:16))}
}

struct PaywallView:View{
    @Environment(\.dismiss)private var dismiss;@EnvironmentObject private var purchase:PurchaseController;@EnvironmentObject private var store:KanriLearningStore
    var body:some View{NavigationStack{VStack(alignment:.leading,spacing:18){Text("管理栄養士 プレミアム").font(LearningSprintTheme.serif(30,weight:.bold));Text("無料版は第1回の各分野6問、合計60問。プレミアムでは全600問・第1〜第3回・200問模試3回を利用できます。");Label("買い切り・広告なし",systemImage:"checkmark.circle.fill");Label("完全オフライン学習",systemImage:"checkmark.circle.fill");Label("苦手復習・履歴・途中再開",systemImage:"checkmark.circle.fill");Spacer();if store.isPremium{Text("購入済みです").font(.headline).foregroundStyle(LearningSprintTheme.green)}else{Button(purchase.displayPrice.map{"購入する（\($0)）"} ?? "価格を取得中"){Task{await purchase.purchase();if purchase.isPremium{dismiss()}}}.buttonStyle(.borderedProminent).tint(LearningSprintTheme.indigo).frame(maxWidth:.infinity,minHeight:50).disabled(purchase.product==nil);Button("購入を復元"){Task{await purchase.restore();if purchase.isPremium{dismiss()}}}.buttonStyle(.bordered).tint(LearningSprintTheme.indigo).frame(maxWidth:.infinity,minHeight:44)}}.padding(24).background(LearningSprintTheme.paper.ignoresSafeArea()).toolbar{ToolbarItem(placement:.topBarTrailing){Button("閉じる"){dismiss()}}}}}
}
